<?php
namespace App\Http\Controllers\Api\V1;
use App\Jobs\{DeliverErpNotification,GenerateReportExport,RunAutomationRule}; use App\Models\{ApprovalDefinition,ApprovalRequest,ApprovalStep,ApprovalDelegation,ErpNotification,ReportExport,ScheduledReport,AutomationRule}; use App\Services\{ApprovalService,AuthorizationService}; use App\Support\TenantContext; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
final class WorkflowController {
 public function definitions(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'approvals.manage'),403);return response()->json(['data'=>ApprovalDefinition::where('tenant_id',$t)->with('steps')->paginate(25)]);}
 public function storeDefinition(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'nullable|uuid','scenario'=>'required|string|max:80','name'=>'required|string|max:150','allow_self_approval'=>'sometimes|boolean','steps'=>'required|array|min:1','steps.*.level'=>'required|integer|min:1','steps.*.permission'=>'required|string|max:100','steps.*.department_id'=>'nullable|uuid','steps.*.minimum_amount'=>'nullable|numeric|min:0','steps.*.maximum_amount'=>'nullable|numeric|min:0']);abort_unless($auth->allows($r->user(),$t,'approvals.manage',$d['company_id']??null),403);$definition=ApprovalDefinition::create(['tenant_id'=>$t,'company_id'=>$d['company_id']??null,'scenario'=>$d['scenario'],'name'=>$d['name'],'allow_self_approval'=>$d['allow_self_approval']??false]);foreach($d['steps'] as $step)ApprovalStep::create([...$step,'tenant_id'=>$t,'definition_id'=>$definition->id]);return response()->json(['data'=>$definition->load('steps')],201);}
 public function submit(Request $r,ApprovalService $approvals,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['scenario'=>'required|string','company_id'=>'nullable|uuid','department_id'=>'nullable|uuid','document_type'=>'required|string','document_id'=>'required|uuid','amount'=>'required|numeric|min:0']);abort_unless($auth->allows($r->user(),$t,'approvals.request',$d['company_id']??null,null,$d['department_id']??null),403);return response()->json(['data'=>$approvals->create([...$d,'tenant_id'=>$t,'requester_id'=>$r->user()->id])],201);}
 public function inbox(Request $r,ApprovalService $approvals){$t=app(TenantContext::class)->id();$requests=ApprovalRequest::where('tenant_id',$t)->where('state','pending')->with(['definition.steps','actions'])->get()->filter(function($request)use($approvals,$r){$step=$request->definition->steps->firstWhere('level',$request->current_level);return $step&&$approvals->eligible($request,$r->user(),$step);})->values();return response()->json(['data'=>$requests]);}
 public function decide(Request $r,ApprovalRequest $approvalRequest,ApprovalService $approvals){abort_unless($approvalRequest->tenant_id===app(TenantContext::class)->id(),404);$d=$r->validate(['decision'=>'required|in:approved,rejected','comment'=>'nullable|string']);return response()->json(['data'=>$approvals->decide($approvalRequest,$r->user(),$d['decision'],$d['comment']??null)]);}
 public function delegate(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['delegate_id'=>'required|uuid','scenario'=>'nullable|string','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at']);abort_unless($auth->allows($r->user(),$t,'approvals.manage'),403);return response()->json(['data'=>ApprovalDelegation::create([...$d,'tenant_id'=>$t,'delegator_id'=>$r->user()->id,'is_active'=>true])],201);}
 public function notifications(Request $r){$t=app(TenantContext::class)->id();return response()->json(['data'=>ErpNotification::where('tenant_id',$t)->where('user_id',$r->user()->id)->latest()->paginate(30)]);}
 public function readNotification(Request $r,ErpNotification $notification){abort_unless($notification->tenant_id===app(TenantContext::class)->id()&&$notification->user_id===$r->user()->id,404);$notification->update(['read_at'=>now()]);return response()->json(['data'=>$notification->fresh()]);}
 public function export(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['report_key'=>'required|in:trial_balance','format'=>'required|in:csv','filters'=>'required|array']);abort_unless($auth->allows($r->user(),$t,'reports.export'),403);$export=ReportExport::create(['tenant_id'=>$t,'requested_by'=>$r->user()->id,'report_key'=>$d['report_key'],'format'=>$d['format'],'filters'=>$d['filters'],'state'=>'queued']);GenerateReportExport::dispatch($t,$export->id);return response()->json(['data'=>$export],202);}
 public function exports(Request $r){return response()->json(['data'=>ReportExport::where('tenant_id',app(TenantContext::class)->id())->where('requested_by',$r->user()->id)->latest()->paginate(25)]);}
 public function download(Request $r,ReportExport $export){abort_unless($export->tenant_id===app(TenantContext::class)->id()&&$export->requested_by===$r->user()->id,404);abort_unless($export->state==='completed'&&$export->private_path,409);return response()->download(Storage::disk('local')->path($export->private_path),$export->report_key.'.csv');}
 public function automation(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'automation.manage'),403);return response()->json(['data'=>AutomationRule::where('tenant_id',$t)->latest()->paginate(25)]);}
 public function storeAutomation(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'automation.manage'),403);$d=$r->validate(['event_key'=>'required|string|max:100','name'=>'required|string|max:150','conditions'=>'nullable|array','actions'=>'required|array']);return response()->json(['data'=>AutomationRule::create([...$d,'tenant_id'=>$t])],201);}
 public function scheduleReport(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($auth->allows($r->user(),$t,'reports.schedule'),403);$d=$r->validate(['company_id'=>'nullable|uuid','report_key'=>'required|in:trial_balance','format'=>'required|in:csv','filters'=>'required|array','cron_expression'=>'required|string|max:100','next_run_at'=>'nullable|date']);return response()->json(['data'=>ScheduledReport::create([...$d,'tenant_id'=>$t,'created_by'=>$r->user()->id,'state'=>'active'])],201);}
 public function scheduledReports(Request $r){return response()->json(['data'=>ScheduledReport::where('tenant_id',app(TenantContext::class)->id())->where('created_by',$r->user()->id)->latest()->paginate(25)]);}
 public function runAutomation(Request $r,AutomationRule $rule){abort_unless($rule->tenant_id===app(TenantContext::class)->id(),404);$key=$r->validate(['idempotency_key'=>'required|string|max:100'])['idempotency_key'];RunAutomationRule::dispatch($rule->tenant_id,$rule->id,$key);return response()->json(['status'=>'queued'],202);}
}
